export function wrapGuard(definition,prefix){
 if(!/^CREATE TRIGGER dbo\.test_guard_[a-z_]+ ON dbo\.[a-z_]+ AFTER INSERT,UPDATE,DELETE AS BEGIN/.test(definition))throw Error('UNKNOWN_LEGACY_GUARD_FORMAT');
 const at=definition.indexOf(' AS BEGIN')+' AS BEGIN'.length;
 // SQL Server stores ALTER TRIGGER definitions with a CREATE header. Predict
 // that canonical stored text independently; execute ALTER without dropping it.
 return definition.slice(0,at)+ '\n'+prefix+'\n'+definition.slice(at);
}
export function buildNightSql(exported){
 const defs=exported?.resultSets?.[0],columns=exported?.resultSets?.[1];if(!Array.isArray(defs)||!Array.isArray(columns))throw Error('EXACT_EXPORT_REQUIRED');
 const list=specs(columns),wrapped=[];
 for(const [name,table,candidate,body] of list){
  const old=defs.find(o=>o.name===name);if(!old||old.is_disabled!==false||old.table_name!==table||sqlHash(old.definition)!==PREVIOUS_GUARDS[name]||old.object_sha!==PREVIOUS_GUARDS[name])throw Error('OLD_GUARD_PIN_MISMATCH_'+name);
  const prefix=`/* ${NIGHT_RUN}: exact synthetic branch; every legacy body character is retained. */\n${identity}\n${preserved}\nIF EXISTS(SELECT 1 FROM inserted i WHERE ${candidate('i')}) OR EXISTS(SELECT 1 FROM deleted d WHERE ${candidate('d')}) BEGIN\nIF EXISTS(SELECT 1 FROM inserted i WHERE NOT(${candidate('i')})) OR EXISTS(SELECT 1 FROM deleted d WHERE NOT(${candidate('d')})) ${fail}\n${body}\nRETURN; END;`;
  wrapped.push({name,table,before:old.definition,beforeHash:old.object_sha,after:wrapGuard(old.definition,prefix)});
 }
 const objects=[readyDefinition(),contextDefinition(),effectsDefinition()];
 return {wrapped,objects};
}

function ownedTrigger(table,body){return `CREATE TRIGGER dbo.work_night_guard_${table} ON dbo.${table} WITH EXECUTE AS OWNER AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; ${identity}\n${body}\nEND;`;}
